/* @PluginInfo(
	shortDescription = "Debugger platform service plugin",
	description = "Selects and manages platforms for the current focus",
	category = PluginCategoryNames.DEBUGGER,
	packageName = DebuggerPluginPackage.NAME,
	status = PluginStatus.RELEASED,
	eventsConsumed = {
		typeof(TraceClosedPluginEvent),
	},
	servicesRequired = {
		typeof(DebuggerTraceManagerService),
	},
	servicesProvided = {
		typeof(DebuggerPlatformService),
	}) */
public class DebuggerPlatformServicePlugin : Plugin, DebuggerPlatformService {

	/* @AutoServiceConsumed */
	private DebuggerTraceManagerService traceManager;
	/* @SuppressWarnings("unused") */
	private AutoService.Wiring autoServiceWiring;

	private Map<Trace, DebuggerPlatformMapper> mappersByTrace = new();

	public DebuggerPlatformServicePlugin(PluginTool tool) : base(tool)
    {
		this.autoServiceWiring = AutoService.wireServicesProvidedAndConsumed(this);
	}

	/* @Override */
	public DebuggerPlatformMapper getCurrentMapperFor(Trace trace) {
		lock (mappersByTrace) {
			return mappersByTrace.get(trace);
		}
	}

	/* @Override */
	public DebuggerPlatformMapper getMapper(Trace trace, TraceObject @object, long snap) {
		/**
		 * TODO: There's a chance different components fight over the current mapper. However, I
		 * suspect all nodes in a trace will yield the same offers, so perhaps I should not worry.
		 */
		DebuggerPlatformMapper mapper;
		lock (mappersByTrace) {
			mapper = mappersByTrace.get(trace);
			if (mapper != null && mapper.canInterpret(@object, snap)) {
				return mapper;
			}
			mapper = getNewMapper(trace, @object, snap);
			if (mapper == null) {
				return null;
			}
			mappersByTrace.put(trace, mapper);
		}
		firePluginEvent(new DebuggerPlatformPluginEvent(getName(), trace, mapper));
		return mapper;
	}

	/* @Override */
	public DebuggerPlatformMapper getNewMapper(Trace trace, TraceObject @object, long snap) {
		if (!traceManager.getOpenTraces().contains(trace)) {
			throw new IllegalArgumentException("Trace is not opened in this tool");
		}
		foreach (DebuggerPlatformOffer offer in DebuggerPlatformOpinion.queryOpinions(trace, @object,
			snap, false)) {
			return offer.take(tool, trace);
		}
		return null;
	}

	/* @Override */
	public void setCurrentMapperFor(Trace trace, TraceObject focus, DebuggerPlatformMapper mapper, long snap) {
		Objects.requireNonNull(trace);
		Objects.requireNonNull(mapper);
		if (!traceManager.getOpenTraces().contains(trace)) {
			throw new IllegalArgumentException("Trace is not opened in this tool");
		}
		lock (mappersByTrace) {
			mappersByTrace.put(trace, mapper);
		}
		TracePlatform platform = mapper.addToTrace(focus, snap);
		firePluginEvent(new DebuggerPlatformPluginEvent(getName(), trace, mapper));
		if (traceManager.getCurrentTrace() == trace) {
			traceManager.activatePlatform(platform);
		}
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		base.processEvent(@event);
		if (@event is TraceClosedPluginEvent) {
			TraceClosedPluginEvent ev = (TraceClosedPluginEvent) @event;
			lock (mappersByTrace) {
				mappersByTrace.remove(ev.getTrace());
			}
		}
	}
}
